CREATE TABLE public.font_catalog(key text PRIMARY KEY,family text NOT NULL,category text NOT NULL CHECK(category IN ('serif','sans','mono','display','slab','script','unknown')),source text NOT NULL CHECK(source IN ('google','commercial','system')),license_hint text NOT NULL CHECK(license_hint IN ('free','commercial','system')),updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.font_catalog TO anon,authenticated; GRANT ALL ON public.font_catalog TO service_role; ALTER TABLE public.font_catalog ENABLE ROW LEVEL SECURITY; CREATE POLICY public_font_catalog ON public.font_catalog FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.font_usage(key text NOT NULL,scope text NOT NULL,role text NOT NULL,data jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(key,scope,role)); GRANT SELECT ON public.font_usage TO anon,authenticated;GRANT ALL ON public.font_usage TO service_role;ALTER TABLE public.font_usage ENABLE ROW LEVEL SECURITY;CREATE POLICY public_font_usage ON public.font_usage FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.font_pairs(key text PRIMARY KEY,data jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());GRANT SELECT ON public.font_pairs TO anon,authenticated;GRANT ALL ON public.font_pairs TO service_role;ALTER TABLE public.font_pairs ENABLE ROW LEVEL SECURITY;CREATE POLICY public_font_pairs ON public.font_pairs FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.color_tickers(key text NOT NULL,scope text NOT NULL,data jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(key,scope));GRANT SELECT ON public.color_tickers TO anon,authenticated;GRANT ALL ON public.color_tickers TO service_role;ALTER TABLE public.color_tickers ENABLE ROW LEVEL SECURITY;CREATE POLICY public_color_tickers ON public.color_tickers FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.palette_examples(domain text PRIMARY KEY,data jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());GRANT SELECT ON public.palette_examples TO anon,authenticated;GRANT ALL ON public.palette_examples TO service_role;ALTER TABLE public.palette_examples ENABLE ROW LEVEL SECURITY;CREATE POLICY public_palette_examples ON public.palette_examples FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.tool_cache(hash text PRIMARY KEY,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days');GRANT ALL ON public.tool_cache TO service_role;ALTER TABLE public.tool_cache ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.crawl_requests(url text PRIMARY KEY,domain text NOT NULL,requested_at timestamptz NOT NULL DEFAULT now(),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','done','error')));GRANT ALL ON public.crawl_requests TO service_role;ALTER TABLE public.crawl_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ai_budget DROP CONSTRAINT ai_budget_scope_check;ALTER TABLE public.ai_budget ADD CONSTRAINT ai_budget_scope_check CHECK(scope IN ('monthly','backfill','public'));
ALTER TABLE public.ai_usage DROP CONSTRAINT ai_usage_kind_check;ALTER TABLE public.ai_usage ADD CONSTRAINT ai_usage_kind_check CHECK(kind IN ('vision','pricing','changelog','product','brief','taste_brief','taste_vision','taste_fonts'));
CREATE FUNCTION public.ai_reserve(p_snapshot_id bigint,p_kind text,p_model text,p_estimate numeric,p_scope text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE b record;spent numeric;uid bigint;BEGIN
IF p_scope<>'public' OR p_kind NOT IN ('taste_brief','taste_vision','taste_fonts') OR p_estimate<=0 OR p_estimate>1 THEN RAISE EXCEPTION 'Invalid public reservation';END IF;
PERFORM pg_advisory_xact_lock(hashtextextended('library-ai-budget',0));
IF (SELECT count(*) FROM public.ai_usage WHERE scope='public' AND created_at>=date_trunc('day',now()) AND state<>'rejected')>=300 THEN RETURN jsonb_build_object('ok',false,'code','Public AI daily limit reached (300 calls); try tomorrow');END IF;
SELECT * INTO b FROM public.ai_budget WHERE scope='public' AND active AND (ends_at IS NULL OR ends_at>now()); SELECT coalesce(sum(est_cost_usd),0) INTO spent FROM public.ai_usage WHERE scope='public' AND created_at>=date_trunc('month',now()) AND state<>'rejected';
IF b.scope IS NULL OR spent+p_estimate>least(b.cap_usd,5) THEN RETURN jsonb_build_object('ok',false,'code','Public AI monthly budget reached ($5); use non-AI tools');END IF;
INSERT INTO public.ai_usage(kind,model,est_cost_usd,scope)VALUES(p_kind,p_model,p_estimate,'public')RETURNING id INTO uid;RETURN jsonb_build_object('ok',true,'id',uid);END;$$; REVOKE ALL ON FUNCTION public.ai_reserve(bigint,text,text,numeric,text) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.ai_reserve(bigint,text,text,numeric,text) TO service_role;
CREATE OR REPLACE FUNCTION public.ai_reserve(p_snapshot_id bigint,p_kind text,p_model text,p_estimate numeric) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE b record; spent numeric; uid bigint;
BEGIN
 IF p_estimate<=0 OR p_estimate>1 THEN RAISE EXCEPTION 'Invalid estimate'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('library-ai-budget',0));
 IF EXISTS(SELECT 1 FROM public.ai_usage WHERE snapshot_id=p_snapshot_id AND kind=p_kind AND state IN ('reserved','unknown')) THEN RETURN jsonb_build_object('ok',false,'code','already_claimed'); END IF;
 FOR b IN SELECT * FROM public.ai_budget WHERE scope IN ('monthly','backfill') AND active AND (ends_at IS NULL OR ends_at>now()) ORDER BY CASE scope WHEN 'backfill' THEN 0 ELSE 1 END LOOP
 SELECT coalesce(sum(est_cost_usd),0) INTO spent FROM public.ai_usage WHERE scope=b.scope AND state<>'rejected' AND (b.scope='backfill' OR created_at>=date_trunc('month',now()));
 IF spent+p_estimate<=b.cap_usd THEN INSERT INTO public.ai_usage(kind,model,est_cost_usd,snapshot_id,scope) VALUES(p_kind,p_model,p_estimate,p_snapshot_id,b.scope) RETURNING id INTO uid; RETURN jsonb_build_object('ok',true,'id',uid,'scope',b.scope); END IF;
 END LOOP;
 RETURN jsonb_build_object('ok',false,'code','budget_exhausted');
END; $$;
CREATE FUNCTION public.replace_taste_data(p_catalog jsonb,p_usage jsonb,p_pairs jsonb,p_colors jsonb,p_palettes jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$BEGIN PERFORM pg_advisory_xact_lock(hashtextextended('taste-refresh',0));
DELETE FROM public.font_usage WHERE key IS NOT NULL;DELETE FROM public.font_pairs WHERE key IS NOT NULL;DELETE FROM public.color_tickers WHERE key IS NOT NULL;DELETE FROM public.palette_examples WHERE domain IS NOT NULL;
INSERT INTO public.font_catalog(key,family,category,source,license_hint)SELECT key,family,category,source,license_hint FROM jsonb_to_recordset(p_catalog)AS x(key text,family text,category text,source text,license_hint text)ON CONFLICT(key)DO UPDATE SET family=excluded.family,category=CASE WHEN excluded.category='unknown' THEN font_catalog.category ELSE excluded.category END,source=excluded.source,license_hint=excluded.license_hint,updated_at=now();
INSERT INTO public.font_usage(key,scope,role,data)SELECT key,scope,role,data FROM jsonb_to_recordset(p_usage)AS x(key text,scope text,role text,data jsonb); INSERT INTO public.font_pairs(key,data)SELECT key,data FROM jsonb_to_recordset(p_pairs)AS x(key text,data jsonb);INSERT INTO public.color_tickers(key,scope,data)SELECT key,scope,data FROM jsonb_to_recordset(p_colors)AS x(key text,scope text,data jsonb);INSERT INTO public.palette_examples(domain,data)SELECT domain,data FROM jsonb_to_recordset(p_palettes)AS x(domain text,data jsonb);DELETE FROM public.tool_cache WHERE expires_at<=now();END;$$;REVOKE ALL ON FUNCTION public.replace_taste_data(jsonb,jsonb,jsonb,jsonb,jsonb) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.replace_taste_data(jsonb,jsonb,jsonb,jsonb,jsonb)TO service_role;